(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const media={
na:{id:'na',name:'Nutrient Agar',abbr:'NA',kind:'general',classif:'General-purpose',state:'Solid (when agar is included)',color:'na',appearance:'Pale amber to light straw',purpose:'A general-purpose solid medium for cultivating many non-fastidious bacteria in appropriate teaching-laboratory settings.',ingredients:[['Peptone','Provides peptides and amino acids.'],['Beef extract or yeast extract','Supplies nutrients and growth factors; exact formulation varies.'],['Sodium chloride','Contributes to osmotic balance when included.'],['Agar','Acts as a solidifying agent.'],['Distilled water','Acts as the solvent.']],notes:'Commercial dehydrated nutrient agar formulations vary. Use the product label for real work; the illustrative values in this lab are not a universal recipe.',limitations:'General-purpose does not mean suitable for every organism. Visual appearance alone does not confirm composition or sterility.',targetPH:'Formulation-dependent; check the manufacturer label.',summary:'A useful baseline for learning how a general-purpose medium differs from specialized media.'},
pda:{id:'pda',name:'Potato Dextrose Agar',abbr:'PDA',kind:'fungal',classif:'Common fungal medium',state:'Solid (when agar is included)',color:'pda',appearance:'Pale amber to light golden',purpose:'Commonly used for cultivation and observation of many fungi, yeasts and moulds in appropriate settings.',ingredients:[['Potato infusion or commercial base','Supplies nutrients from the potato-derived infusion or formulated base.'],['Dextrose','Provides a carbon and energy source.'],['Agar','Solidifies the medium.'],['Water','Acts as the solvent.']],notes:'Appearance and composition vary with the formulation. Use an appropriate commercial product label or approved teaching-lab reference.',limitations:'Not all fungi have the same requirements. This educational simulation does not provide instructions for cultivating harmful fungi.',targetPH:'Formulation-dependent; verify the selected product documentation.',summary:'PDA is often introduced when learning about media used for many fungi and yeasts.'},
mac:{id:'mac',name:'MacConkey Agar',abbr:'MAC',kind:'differential',classif:'Selective and differential',state:'Solid',color:'mac',appearance:'Pinkish to reddish medium',purpose:'A selective and differential medium used in appropriate laboratory settings to help distinguish certain Gram-negative enteric bacteria by lactose fermentation.',ingredients:[['Selective agents','Suppress some groups of organisms, depending on formulation.'],['Lactose','Provides the substrate used to demonstrate lactose fermentation.'],['pH indicator','Signals acid-associated changes through a colour shift.'],['Peptones and salts','Provide nutrients and help maintain formulation properties.'],['Agar and water','Provide a solid matrix and solvent.']],notes:'Exact ingredients and interpretation criteria are product-specific. This lab uses illustrative plate colours, not diagnostic results.',limitations:'Colony appearance alone cannot confirm an organism identity. Never use this exercise to handle unknown or potentially pathogenic bacteria.',targetPH:'Use the formulation label for any supported target range.',summary:'MacConkey agar teaches the difference between selectivity and differentiation.'},
sda:{id:'sda',name:'Sabouraud Dextrose Agar',abbr:'SDA',kind:'fungal',classif:'Common fungal medium',state:'Solid (when agar is included)',color:'sda',appearance:'Light amber',purpose:'A medium commonly used for cultivating many fungi and yeasts in appropriate settings.',ingredients:[['Peptone','Provides peptides and nitrogen-containing nutrients.'],['Dextrose','Provides a carbon and energy source.'],['Agar','Solidifies the medium.'],['Water','Acts as the solvent.']],notes:'Formulations and pH differ; selective additives, when present, change intended use. Follow product-specific instructions in real work.',limitations:'A general description does not validate a specific application. No harmful-fungi cultivation instructions are included.',targetPH:'Formulation-dependent; consult the manufacturer.',summary:'SDA highlights how formulation and pH relate to a medium’s intended use.'}
};
const mediaOrder=['na','pda','mac','sda'];
const stageData=[
{title:'Choose & plan',short:'Purpose and composition',instruction:'Choose a medium that matches the learning objective. Review its intended use and formulation notes before proceeding.',science:'Media are designed around a purpose. General-purpose, fungal, and selective/differential media are not interchangeable.',expected:'A selected medium card, an educational target volume, and a clear ingredient list.',mistake:'Choosing a medium by colour or name alone instead of its intended use.',why:'The medium’s formulation determines its properties and the limits of what can be inferred from it.'},
{title:'Review quantities',short:'Proportional calculation',instruction:'Use the volume calculator to see how an illustrative reference quantity scales. These sample values teach the calculation only.',science:'When the same formulation is scaled, quantity changes in proportion to volume: reference quantity × target volume ÷ reference volume.',expected:'The displayed illustrative quantities update when the target volume changes.',mistake:'Treating an educational example as a manufacturer-approved recipe.',why:'Product formulations vary. Scaling mathematics is general, but the correct reference values must come from the chosen product documentation.'},
{title:'Weigh & combine',short:'Ingredient awareness',instruction:'Select ingredient jars and add virtual amounts to the balance. Compare the simulated reading with the illustrative target and then add ingredients to the vessel.',science:'Accurate measurement supports consistency. Ingredient identity and quantity both matter; a correct mass of the wrong ingredient is still an error.',expected:'A numerical simulated balance reading and ingredient checklist updates.',mistake:'Missing an ingredient or assuming a plausible mass proves the correct composition.',why:'Ingredient functions differ. The balance is a teaching control, not a calibrated instrument.'},
{title:'Mix & inspect pH',short:'Dissolving and pH',instruction:'Use the mixing control to make the virtual medium uniform. Explore the pH station and observe how a simplified model changes.',science:'Dissolving distributes components. pH is influenced by formulation and buffering capacity; a simplified slider cannot predict real chemistry.',expected:'The simulated mixture becomes uniform and a clearly labelled illustrative pH reading changes.',mistake:'Assuming a simulated pH change models the chemistry of a real buffered medium.',why:'Real pH adjustment depends on the product, measurement conditions, and approved procedure.'},
{title:'Process & cool',short:'Simulated processing',instruction:'Advance through the virtual processing and cooling states. Review the equipment and manufacturer/SOP caveat.',science:'Validated processing depends on the medium, equipment, manufacturer instructions and laboratory SOP.',expected:'A simulated processing state and then a cooling-ready state.',mistake:'Treating an animation or a visual check as proof of sterility.',why:'A website cannot verify real-world sterility. Real processing requires validated methods and appropriate quality controls.'},
{title:'Transfer & reflect',short:'Plate and report',instruction:'Transfer the virtual medium into a dish, observe the illustrative final appearance, then review your report.',science:'Agar-containing medium can form a solid matrix as it cools. An uninoculated plate does not spontaneously grow colonies.',expected:'A simulated plate with a labelled representative medium appearance; no automatic colonies.',mistake:'Interpreting illustrative colony examples as proof of organism identity.',why:'Observation is only one part of scientific interpretation; identity and safety require appropriate validated methods.'}
];
const challenges=[
{title:'The missing solidifier',desc:'A student is reviewing a virtual general-purpose plate medium. The record shows a nutrient base and water, but no solidifying agent.',evidence:['The learning objective asks for a solid medium.','The ingredient checklist has no agar entry.','The vessel is shown as a liquid in the final-stage preview.'],q:'What is the most relevant issue?',opts:['The medium is missing a solidifying agent for the stated goal.','The colour is too pale to be useful.','The virtual plate needs colonies before it can be considered prepared.'],correct:0,explain:'Agar is commonly used to solidify a medium. Without a suitable solidifier, the simulation should not represent this as a solid plate. Appearance alone is not the criterion.'},
{title:'The wrong learning objective',desc:'A learner chooses a medium described as selective and differential for a task that only asks them to compare general-purpose nutrient support.',evidence:['The task is about broad, non-fastidious teaching examples.','The selected medium has selective agents and a lactose indicator.','No reason for selective/differential properties is stated.'],q:'What should the learner do?',opts:['Choose the medium with the brightest colour.','Revisit the objective and select a medium whose purpose fits it.','Assume all media are interchangeable if they are solid.'],correct:1,explain:'Medium choice should follow the learning objective. Specialized selective/differential properties are not a universal advantage and do not make media interchangeable.'},
{title:'Reading the balance',desc:'A simulated target ingredient mass is shown, but the balance reading is well above the illustrative target range.',evidence:['The displayed mass exceeds the target range.','The ingredient identity is correct.','The virtual vessel has not yet been marked as complete.'],q:'What is the best next step in this simulation?',opts:['Ignore the reading because the ingredient is correct.','Add more of the same ingredient to average it out.','Remove virtual material and re-check the reading against the target.'],correct:2,explain:'Both ingredient identity and quantity matter. In this simulation, remove excess virtual material and re-check. Real measurements require calibrated equipment and approved procedures.'},
{title:'An unsupported pH claim',desc:'A learner says the displayed pH slider proves the real medium will reach the same value after adding a simulated acid or base.',evidence:['The interface labels pH as a simplified educational model.','The medium composition and buffering capacity influence pH response.','No real measurement or product documentation is involved.'],q:'Which interpretation is scientifically sound?',opts:['The slider predicts the exact real-world pH.','The simulated reading illustrates a concept and does not predict real chemistry.','pH is unrelated to formulation.'],correct:1,explain:'pH response depends on composition and buffering capacity. This simplified model is illustrative and must not be treated as a real chemical prediction.'},
{title:'Colony colour and identity',desc:'A learner sees a simulated pink colony example on a differential medium and writes that the organism is definitively identified.',evidence:['The plate visual is labelled illustrative.','Colony appearance can reflect a differential reaction.','No validated identification workflow is shown.'],q:'What is the main reasoning error?',opts:['Treating an illustrative colony appearance as definitive identification.','Using a label on a plate.','Not selecting a darker medium.'],correct:0,explain:'Colony appearance alone does not confirm organism identity. The visual is an educational example; validated identification and biosafety procedures are essential in real work.'}
];
const questions=[
{q:'Which ingredient category commonly provides peptides and amino acids in nutrient agar?',opts:['Agar','Peptone','Distilled water','pH indicator'],a:1,explain:'Peptone supplies peptides and amino acids. Agar primarily provides a solidifying matrix.'},
{q:'What is the main role of agar in a solid medium?',opts:['Provide the primary carbon source','Identify every organism present','Act as a solidifying agent','Guarantee sterility'],a:2,explain:'Agar is used to form a solid matrix. It does not guarantee sterility or identify organisms.'},
{q:'Which medium is commonly used for many fungi, yeasts and moulds?',opts:['Potato Dextrose Agar','Only nutrient broth','MacConkey Agar for all organisms','Distilled water alone'],a:0,explain:'PDA is commonly used for many fungi, yeasts and moulds. A specific application still depends on formulation and approved guidance.'},
{q:'MacConkey agar is best described as:',opts:['A universal identity test','Selective and differential','A sterile-water substitute','A medium without indicators'],a:1,explain:'MacConkey agar is selective and differential in appropriate settings, including differentiation based on lactose fermentation.'},
{q:'What does dextrose provide in PDA and SDA formulations?',opts:['A carbon and energy source','The solidifying matrix','A calibrated mass reading','Proof of sterility'],a:0,explain:'Dextrose is a carbon and energy source. Agar, when present, provides solidification.'},
{q:'An illustrative formula uses 12 g per 500 mL. What quantity scales proportionally to 250 mL?',opts:['3 g','6 g','12 g','24 g'],a:1,explain:'12 × 250 ÷ 500 = 6 g. This checks proportional arithmetic only; it is not a validated formulation recommendation.'},
{q:'A simulated pH slider shows a target range. What does that establish about a real medium?',opts:['It proves the real pH','It proves sterility','Nothing by itself; consult formulation-specific instructions and real measurements','It identifies the organism'],a:2,explain:'The simplified pH model illustrates a concept only. Real pH depends on formulation, buffering capacity, conditions and measurement.'},
{q:'A clean uninoculated virtual plate has no colonies. Is that unexpected?',opts:['Yes, colonies should appear automatically','No, an uninoculated plate should not be shown as spontaneously growing colonies','Yes, colour alone proves contamination','Only if the medium is amber'],a:1,explain:'The simulation keeps a clean plate uninoculated. Any colony examples are separate illustrative observations, not automatic growth or definitive identification.'}
];
const state={page:'overview',medium:'na',volume:250,stage:0,completedStages:[],selectedTool:null,ingredientsAdded:{},balance:0,mixture:0,ph:6.8,processed:false,cooled:false,plated:false,errorsCorrected:0,challengeIndex:0,challengeAnswers:{},challengeScore:0,quizIndex:0,quizAnswers:{},quizScore:0,quizStarted:Date.now(),quizComplete:false,libraryFilter:'all',librarySelected:null,equipmentSelected:null,history:[],skills:new Set(),lastReport:null};
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2600)}
function save(){try{localStorage.setItem('culturecraft-state',JSON.stringify({...state,skills:[...state.skills],quizStarted:state.quizStarted}))}catch(e){}}
function load(){try{const x=JSON.parse(localStorage.getItem('culturecraft-state')||'null');if(x){Object.assign(state,x);state.skills=new Set(x.skills||[]);}}catch(e){}}
function go(page){if(!$('#page-'+page))return;state.page=page;$$('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+page));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').textContent=({overview:'Lab overview',lab:'Media preparation lab',library:'Culture media library',equipment:'Virtual equipment room',compare:'Media comparison',challenge:'Error detection challenge',quiz:'Quiz & assessment',report:'Experiment report'})[page]||page;$('#sidebar').classList.remove('open');if(page==='lab')renderLab();if(page==='library')renderLibrary();if(page==='equipment')renderEquipment();if(page==='compare')renderCompare();if(page==='challenge')renderChallenge();if(page==='quiz')renderQuiz();if(page==='report')renderReport();window.scrollTo({top:0,behavior:'smooth'});save()}
function current(){return media[state.medium]||media.na}
function referenceAmounts(){const ref={na:{peptone:5,extract:3,salt:5,agar:15},pda:{potato:4,dextrose:20,agar:15},mac:{base:50},sda:{peptone:10,dextrose:40,agar:15}};return ref[state.medium]||ref.na}
function scaledAmounts(){const f=state.volume/1000;return Object.fromEntries(Object.entries(referenceAmounts()).map(([k,v])=>[k,v*f]))}
function ingredientLabels(){return {peptone:'Peptone',extract:'Extract',salt:'Sodium chloride',agar:'Agar',potato:'Potato-derived base',dextrose:'Dextrose',base:'Commercial dehydrated base'}}
function selectedIngredients(){return Object.keys(referenceAmounts())}
function renderMediaOptions(){$('#mediaOptions').innerHTML=mediaOrder.map(id=>{const m=media[id];return '<button class="media-option '+(id===state.medium?'selected':'')+'" data-medium="'+id+'"><span class="media-swatch swatch-'+m.color+'"></span><b>'+m.name+'</b><small>'+m.classif+'</small></button>'}).join('')}
function renderWorkflow(){$('#workflowList').innerHTML=stageData.map((s,i)=>{const done=state.completedStages.includes(i);return '<button class="workflow-step '+(i===state.stage?'current ':'')+(done?'complete':'')+'" data-stage="'+i+'"><span class="step-number">'+(done?'✓':String(i+1).padStart(2,'0'))+'</span><span class="step-copy"><b>'+s.title+'</b><small>'+s.short+'</small></span><span class="step-state">'+(done?'✓':i===state.stage?'•':'')+'</span></button>'}).join('');$('#workflowCount').textContent=state.completedStages.length+' of 6 complete';$('#stepChip').textContent='STEP '+String(state.stage+1).padStart(2,'0')+' / 06';$('#prevStep').disabled=state.stage===0;$('#prevStep').style.opacity=state.stage===0?'.4':'1';$('#nextStep').innerHTML=state.stage===5?'Complete & view report <span>✓</span>':'Continue to next step <span>→</span>';$('#nextStep').disabled=state.stage===2&&Object.keys(state.ingredientsAdded).length===0;$('#nextStep').style.opacity=$('#nextStep').disabled?'.45':'1';const s=stageData[state.stage];$('#guideTitle').textContent=s.title;$('#guideInstruction').textContent=s.instruction;$('#guideScience').textContent=s.science;$('#guideExpected').textContent=s.expected;$('#guideMistake').textContent=s.mistake;$('#whyContent').hidden=true;$('#whyBtn span').textContent='＋';renderChecklist()}
function renderChecklist(){const items=[['Medium selected',!!state.medium],['Ingredient review',state.stage>1||Object.keys(state.ingredientsAdded).length>0],['Mixing & pH explored',state.mixture>0||state.stage>3],['Processing simulated',state.processed],['Final plate prepared',state.plated]];$('#checklist').innerHTML=items.map(([s,d])=>'<div class="checkline '+(d?'done':'')+'"><span>'+(d?'✓':'')+'</span>'+s+'</div>').join('');$('#checkCount').textContent=items.filter(x=>x[1]).length+'/5'}
function renderLab(){renderMediaOptions();renderWorkflow();$('#volumeInput').value=state.volume;$('#balanceReadout').textContent=state.balance.toFixed(2)+' g';$('#vesselStatus').textContent=state.mixture?'Mixed virtual medium':'Empty vessel';if(!state.selectedTool)renderToolEmpty();else renderTool(state.selectedTool)}
function renderToolEmpty(){$('#toolPanel').innerHTML='<div class="tool-empty"><span>✳</span><div><b>Your bench, your discovery.</b><p>Select any instrument above to open its controls and learn how it works.</p></div></div>';$$('.bench-object').forEach(x=>x.classList.remove('selected'))}
function renderTool(tool){state.selectedTool=tool;$$('.bench-object').forEach(x=>x.classList.toggle('selected',x.dataset.tool===tool));let html='';const m=current(),amt=scaledAmounts();
if(tool==='ingredients'){html='<div class="tool-controls"><div><h3>Ingredient jars</h3><p>Select an ingredient to add its illustrative target amount to the virtual weighing boat. Reference values here are for arithmetic practice only.</p><div class="ingredient-pills">'+selectedIngredients().map(k=>'<button class="ingredient-pill '+(state.ingredientsAdded[k]?'active':'')+'" data-ingredient="'+k+'">'+ingredientLabels()[k]+'</button>').join('')+'</div></div><div><div class="tool-metric">'+Object.keys(state.ingredientsAdded).length+' <small>/ '+selectedIngredients().length+' ingredient categories selected</small></div><p style="font-size:10px;color:#8a968b;line-height:1.7;margin:7px 0 12px">Illustrative target at '+state.volume+' mL: '+selectedIngredients().map(k=>ingredientLabels()[k]+' '+amt[k].toFixed(2)+' g').join(' · ')+'.</p><div class="tool-actions"><button class="small-btn primary" id="addSelected">Add selected to vessel</button><button class="small-btn" id="clearIngredients">Clear selection</button></div></div></div>'}
if(tool==='balance'){html='<div class="tool-controls"><div><h3>Digital balance</h3><p>Simulated reading updates when ingredients are added or removed. No real measurement is being made.</p><div class="tool-metric" style="margin-top:12px">'+state.balance.toFixed(2)+' <small>g · simulated</small></div></div><div><label class="guide-label">ADD OR REMOVE SIMULATED MASS</label><input class="tool-range" id="massRange" type="range" min="0" max="100" step=".5" value="'+Math.min(100,state.balance)+'"><div class="tool-actions" style="margin-top:10px"><button class="small-btn" id="massMinus">− 1 g</button><button class="small-btn" id="massPlus">+ 1 g</button><button class="small-btn" id="tareBalance">Tare / reset</button></div><p style="font-size:9px;color:#929d92;margin-top:8px">Reading is illustrative; target total depends on formulation.</p></div></div>'}
if(tool==='vessel'){html='<div class="tool-controls"><div><h3>Mixing vessel</h3><p>Use the simulated mixing control to move from separate virtual ingredients to a visually uniform mixture.</p><div class="tool-metric">'+(state.mixture?'Uniform':'Not mixed')+' <small>· virtual state</small></div></div><div class="tool-actions"><button class="small-btn primary" id="mixBtn">'+(state.mixture?'Mix again':'Start simulated mixing')+'</button><button class="small-btn" id="emptyVessel">Empty vessel</button></div></div>'}
if(tool==='petri'){html='<div class="tool-controls"><div><h3>Petri dish viewer</h3><p>Transfer is available after the simulated processing and cooling stages. An uninoculated plate remains free of colonies.</p><div class="tool-metric">'+(state.plated?'Plate prepared':'Awaiting transfer')+'</div></div><div class="tool-actions"><button class="small-btn primary" id="plateBtn" '+(!state.cooled?'disabled':'')+'>Transfer to virtual dish</button><button class="small-btn" id="rotateDish">Rotate view ↻</button></div></div>'}
if(tool==='pH'){html='<div class="tool-controls"><div><h3>Virtual pH meter</h3><p>Simplified teaching model only. Real pH depends on formulation and buffering capacity.</p><div class="tool-metric" id="phReadout">'+state.ph.toFixed(1)+' <small>pH · simulated</small></div></div><div><label class="guide-label">ILLUSTRATIVE PH ADJUSTMENT</label><input class="tool-range" id="phRange" type="range" min="3" max="10" step=".1" value="'+state.ph+'"><div class="tool-actions"><button class="small-btn" id="acidBtn">Simulate acid ↓</button><button class="small-btn" id="baseBtn">Simulate base ↑</button></div><p style="font-size:9px;color:#929d92;margin-top:8px">No universal target is implied; consult the selected formulation.</p></div></div>'}
if(tool==='sterilizer'){html='<div class="tool-controls"><div><h3>Simulated processing unit</h3><p>Animation is a conceptual stage, not proof of sterility. Real validated processing depends on the medium, equipment and approved SOP.</p><div class="tool-metric">'+(state.processed?'Stage completed':'Not yet processed')+'</div></div><div class="tool-actions"><button class="small-btn primary" id="processBtn">Run simulated stage</button><button class="small-btn" id="coolBtn" '+(!state.processed?'disabled':'')+'>Advance to cooling</button></div></div>'}
$('#toolPanel').innerHTML=html;bindTool(tool)}
function bindTool(tool){const on=(id,fn)=>{const e=$('#'+id);if(e)e.addEventListener('click',fn)};if(tool==='ingredients'){$$('.ingredient-pill').forEach(b=>b.addEventListener('click',()=>{const k=b.dataset.ingredient;if(state.ingredientsAdded[k])delete state.ingredientsAdded[k];else state.ingredientsAdded[k]=true;renderTool('ingredients')}));on('addSelected',()=>{const a=scaledAmounts();let sum=0;Object.keys(state.ingredientsAdded).forEach(k=>sum+=a[k]||0);if(!Object.keys(state.ingredientsAdded).length){toast('Select at least one ingredient first.');return}state.balance+=sum;state.mixture=0;state.history.push('Added selected illustrative ingredients to the virtual balance');renderLab();renderTool('balance');toast('Virtual ingredient mass added to the simulated balance.');save()});on('clearIngredients',()=>{state.ingredientsAdded={};renderTool('ingredients')})}
if(tool==='balance'){on('massRange',()=>{});const range=$('#massRange');range.addEventListener('input',()=>{state.balance=+range.value;$('#balanceReadout').textContent=state.balance.toFixed(2)+' g';$('.tool-metric').innerHTML=state.balance.toFixed(2)+' <small>g · simulated</small>';save()});on('massMinus',()=>{state.balance=Math.max(0,state.balance-1);renderLab();renderTool('balance')});on('massPlus',()=>{state.balance=Math.min(100,state.balance+1);renderLab();renderTool('balance')});on('tareBalance',()=>{state.balance=0;renderLab();renderTool('balance');toast('Virtual balance reset.')})}
if(tool==='vessel'){on('mixBtn',()=>{state.mixture=1;state.completedStages=[...new Set([...state.completedStages,3])];state.skills.add('mixing');state.history.push('Completed simulated mixing');renderLab();renderTool('vessel');updateProgress();toast('Virtual mixture is now marked uniform.');save()});on('emptyVessel',()=>{state.mixture=0;renderLab();renderTool('vessel');toast('Virtual vessel emptied.')})}
if(tool==='petri'){on('plateBtn',()=>{if(!state.cooled){toast('Complete simulated processing and cooling first.');return}state.plated=true;state.completedStages=[...new Set([...state.completedStages,5])];state.skills.add('plate');state.history.push('Transferred virtual medium to an uninoculated dish');renderLab();renderTool('petri');updateProgress();toast('Virtual plate prepared — no colonies are added.');save()});on('rotateDish',()=>{const dish=$('.petri-drawing');if(dish){dish.style.transform='rotate('+(Math.random()*160-80)+'deg)';dish.style.filter='hue-rotate('+(Math.random()*15)+'deg)'}toast('Viewing angle changed (illustrative).')})}
if(tool==='pH'){const range=$('#phRange');range.addEventListener('input',()=>{state.ph=+range.value;$('#phReadout').innerHTML=state.ph.toFixed(1)+' <small>pH · simulated</small>';save()});on('acidBtn',()=>{state.ph=Math.max(3,Math.round((state.ph-.3)*10)/10);renderTool('pH')});on('baseBtn',()=>{state.ph=Math.min(10,Math.round((state.ph+.3)*10)/10);renderTool('pH')})}
if(tool==='sterilizer'){on('processBtn',()=>{state.processed=true;state.completedStages=[...new Set([...state.completedStages,4])];state.skills.add('processing');state.history.push('Completed simulated processing stage');renderLab();renderTool('sterilizer');updateProgress();toast('Simulation stage complete — this does not prove real sterility.');save()});on('coolBtn',()=>{if(!state.processed)return;state.cooled=true;state.completedStages=[...new Set([...state.completedStages,4])];state.history.push('Advanced virtual medium to cooling state');renderLab();renderTool('petri');toast('Virtual medium marked as cooled.');save()})}}
function setStage(i){if(i>state.stage&&!state.completedStages.includes(state.stage)){if(state.stage===2&&Object.keys(state.ingredientsAdded).length===0){toast('Select and weigh at least one virtual ingredient before continuing.');return}if(state.stage===3&&state.mixture===0){toast('Explore the simulated mixing control before continuing.');return}if(state.stage===4&&!state.processed){toast('Complete the simulated processing stage first.');return}if(state.stage===4&&!state.cooled){toast('Advance through the simulated cooling stage first.');return}state.completedStages.push(state.stage);state.completedStages=[...new Set(state.completedStages)]}if(i<0||i>5)return;state.stage=i;if(i===0)state.completedStages=[...new Set([...state.completedStages,0])];if(i===1)state.completedStages=[...new Set([...state.completedStages,1])];if(i===2&&Object.keys(state.ingredientsAdded).length)state.completedStages=[...new Set([...state.completedStages,2])];renderLab();updateProgress();save()}
function resetLab(){state.medium='na';state.volume=250;state.stage=0;state.completedStages=[];state.selectedTool=null;state.ingredientsAdded={};state.balance=0;state.mixture=0;state.ph=6.8;state.processed=false;state.cooled=false;state.plated=false;state.history=[];state.errorsCorrected=0;renderLab();updateProgress();toast('Experiment restarted.');save()}
function renderLibrary(){const q=($('#librarySearch')?.value||'').toLowerCase();const ids=mediaOrder.filter(id=>{const m=media[id];const hay=[m.name,m.purpose,m.classif,m.ingredients.flat().join(' ')].join(' ').toLowerCase();return (!q||hay.includes(q))&&(state.libraryFilter==='all'||m.kind===state.libraryFilter)});$('#libraryGrid').innerHTML=ids.length?ids.map(id=>{const m=media[id];return '<button class="media-card '+(state.librarySelected===id?'selected':'')+'" data-library="'+id+'"><div class="media-card-top"><span class="media-swatch swatch-'+m.color+'"></span><span class="card-abbr">'+m.abbr+'</span></div><h3>'+m.name+'</h3><p>'+m.purpose+'</p><div class="card-tags"><span class="card-tag">'+m.classif+'</span><span class="card-tag">'+m.state.split(' ')[0]+'</span></div><div class="card-read">Explore medium <span>↗</span></div></button>'}).join(''):'<div class="detail-empty"><span>⌕</span><div><h3>No matching media</h3><p>Try another search term or choose a different filter.</p></div></div>';$$('[data-library]').forEach(b=>b.addEventListener('click',()=>{state.librarySelected=b.dataset.library;renderLibraryDetail(b.dataset.library);renderLibrary()}));$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===state.libraryFilter))}
function renderLibraryDetail(id){const m=media[id];if(!m)return;const agarColors={na:'#e8c777',pda:'#e6c984',mac:'#d98b9e',sda:'#efd8a0'};const ingredientColors=['#d9b77b','#91643d','#f8f8f1','#e7e0ce','#9bc8df'];$('#libraryDetail').innerHTML='<div class="detail-head"><span class="media-swatch swatch-'+m.color+'"></span><div><div class="panel-kicker">'+m.abbr+' / MEDIA PROFILE</div><h2>'+m.name+'</h2><p>'+m.purpose+'</p><div class="card-tags"><span class="card-tag">'+m.classif+'</span><span class="card-tag">'+m.state+'</span></div></div></div><div class="culture-plate-panel"><div class="culture-plate-visual"><div class="culture-plate" style="--agar-color:'+agarColors[id]+'" role="img" aria-label="Illustrative clean culture plate showing '+m.appearance+' agar"></div><div class="plate-caption"><span class="plate-status-dot"></span> Clean virtual plate · no colonies</div></div><div class="plate-info"><span class="panel-kicker">CULTURE PLATE VIEW</span><h3>What the agar looks like</h3><p class="plate-colour-name">'+m.appearance+'</p><p class="plate-description">Representative colour only. The actual shade can vary with manufacturer, formulation, lighting and preparation.</p><div class="plate-legend"><span><i style="background:'+agarColors[id]+'"></i> Agar colour</span><span><i class="legend-rim"></i> Petri dish</span></div><div class="plate-note">This is an illustration of uninoculated medium; no microbial growth is shown.</div></div></div><div class="detail-columns"><div><h3>Ingredients & their functions</h3>'+m.ingredients.map(([a,b],i)=>'<div class="ingredient-row ingredient-visual-row"><span class="ingredient-colour-dot" style="background:'+ingredientColors[i%ingredientColors.length]+'"></span><b>'+a+'</b><span>'+b+'</span></div>').join('')+'</div><div><h3>Properties & considerations</h3><div class="ingredient-row"><b>Appearance</b><span>'+m.appearance+'</span></div><div class="ingredient-row"><b>pH</b><span>'+m.targetPH+'</span></div><div class="ingredient-row"><b>Educational use</b><span>'+m.summary+'</span></div><div class="detail-note"><b>Formulation note</b><br>'+m.notes+'<br><br><b>Limitation</b><br>'+m.limitations+'</div></div></div><div class="knowledge-check"><span class="panel-kicker">QUICK KNOWLEDGE CHECK</span><p>Which statement is the safest interpretation of '+m.name+'?</p><button class="small-btn" data-lib-answer="0">A formulation is universal for every manufacturer.</button><button class="small-btn" data-lib-answer="1">Use and interpretation depend on the specific formulation and approved guidance.</button><div id="libFeedback" class="why-content" hidden></div></div>';$$('[data-lib-answer]').forEach(b=>b.addEventListener('click',()=>{const f=$('#libFeedback');f.hidden=false;f.textContent=b.dataset.libAnswer==='1'?'Correct. Formulation and validated application matter; the library gives general educational context only.':'Not quite. Formulations vary, so use the specific product documentation and approved procedures.';f.style.color=b.dataset.libAnswer==='1'?'#52765a':'#9a7b4b';if(b.dataset.libAnswer==='1'){state.skills.add('media-literacy');updateProgress()}save()}))}
function renderEquipment(){const items=[['balance','⚖','Digital balance','Displays a simulated mass and supports virtual tare/add/remove controls.'],['pH','◉','Virtual pH meter','Explore a simplified pH model and its limitations.'],['sterilizer','▤','Processing unit','Step through an illustrative processing and cooling sequence.'],['ingredients','⚗','Reagent containers','Review ingredient categories and illustrative target quantities.'],['vessel','♧','Mixing vessel','Mark a virtual mixture as uniform and explore the concept of dissolving.'],['petri','◎','Petri dish viewer','Rotate the dish and transfer the cooled virtual medium.']];$('#equipmentGrid').innerHTML=items.map(([id,icon,name,desc])=>'<button class="equipment-card '+(state.equipmentSelected===id?'selected':'')+'" data-equipment="'+id+'"><div class="equipment-icon">'+icon+'</div><h3>'+name+'</h3><p>'+desc+'</p><span>Open instrument →</span></button>').join('');$$('[data-equipment]').forEach(b=>b.addEventListener('click',()=>{state.equipmentSelected=b.dataset.equipment;renderEquipment();renderEquipmentDetail(state.equipmentSelected)}));if(state.equipmentSelected)renderEquipmentDetail(state.equipmentSelected)}
function renderEquipmentDetail(id){const names={balance:'Digital balance',pH:'Virtual pH meter',sterilizer:'Simulated processing unit',ingredients:'Ingredient containers',vessel:'Mixing vessel',petri:'Petri dish viewer'};const descriptions={balance:'A virtual mass readout for practising measurement reasoning. It is not a calibrated instrument.',pH:'A simplified pH control illustrating that pH is formulation-dependent and cannot be predicted precisely here.',sterilizer:'An animation of processing and cooling stages; it is not proof of real-world sterility.',ingredients:'Ingredient labels and illustrative scaling values for learning component functions.',vessel:'A state control for conceptual mixing and dissolving.',petri:'A simulated plate view. Uninoculated plates do not automatically display colonies.'};$('#equipmentDetail').innerHTML='<div class="detail-head"><span class="equipment-icon">'+({balance:'⚖',pH:'◉',sterilizer:'▤',ingredients:'⚗',vessel:'♧',petri:'◎'}[id])+'</span><div><div class="panel-kicker">INSTRUMENT CONSOLE</div><h2>'+names[id]+'</h2><p>'+descriptions[id]+'</p></div></div><div class="equipment-controls"><button class="btn btn-primary" id="useEquipment">Open controls in preparation lab <span>↗</span></button><span class="guide-label">STATE: '+esc(id==='balance'?state.balance.toFixed(2)+' g':id==='pH'?state.ph.toFixed(1)+' pH':id==='sterilizer'?(state.cooled?'Cooled':state.processed?'Processed':'Ready'):id==='petri'?(state.plated?'Plate prepared':'Awaiting transfer'):'Ready')+'</span></div>';$('#useEquipment').addEventListener('click',()=>{go('lab');renderTool(id)})}
function fillCompareSelects(){const opt=mediaOrder.map(id=>'<option value="'+id+'">'+media[id].name+'</option>').join('');$('#compareA').innerHTML=opt;$('#compareB').innerHTML=opt;$('#compareA').value='na';$('#compareB').value='pda'}
function renderCompare(pair){if(pair==='all'){const rows=[['Purpose',...mediaOrder.map(id=>media[id].purpose)],['Classification',...mediaOrder.map(id=>media[id].classif)],['Physical state',...mediaOrder.map(id=>media[id].state)],['Ingredient categories',...mediaOrder.map(id=>media[id].ingredients.map(x=>x[0]).join(', '))],['Representative appearance',...mediaOrder.map(id=>media[id].appearance)],['pH information',...mediaOrder.map(id=>media[id].targetPH)],['Limitations',...mediaOrder.map(id=>media[id].limitations)]];$('#compareResult').innerHTML='<div style="overflow-x:auto"><table class="compare-table"><thead><tr><th>Property</th>'+mediaOrder.map(id=>'<th>'+media[id].name+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><div class="compare-explanation">Remember: media should be selected by intended use and formulation-specific requirements. A shared solid appearance does not make these media interchangeable.</div>';return}const a=media[$('#compareA').value],b=media[$('#compareB').value];const rows=[['Intended use',a.purpose,b.purpose],['Classification',a.classif,b.classif],['Physical state',a.state,b.state],['Key ingredients',a.ingredients.map(x=>x[0]).join(', '),b.ingredients.map(x=>x[0]).join(', ')],['Appearance',a.appearance,b.appearance],['pH information',a.targetPH,b.targetPH],['Important limitations',a.limitations,b.limitations]];$('#compareResult').innerHTML='<table class="compare-table"><thead><tr><th>Property</th><th>'+a.name+'</th><th>'+b.name+'</th></tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table><div class="compare-explanation">'+(a.id==='na'&&b.id==='pda'||a.id==='pda'&&b.id==='na'?'Nutrient agar is a general-purpose medium for many non-fastidious bacteria in appropriate teaching settings, while PDA is commonly used for many fungi and yeasts.':a.kind==='fungal'&&b.kind==='fungal'?'PDA and SDA are both commonly used for many fungi and yeasts, but their formulations and intended applications are not identical. Check product-specific information.':a.id==='mac'||b.id==='mac'?'MacConkey agar has selective and differential properties, unlike a general-purpose nutrient medium. Colony appearance alone does not identify an organism.':'Compare intended use, ingredients, state and limitations together. Similar appearance alone does not establish equivalent performance.')+'</div>'}
function renderChallenge(){const c=challenges[state.challengeIndex];const answered=state.challengeAnswers[state.challengeIndex];$('#challengeScore').textContent=state.challengeScore;$('#challengeProgressBar').style.width=((state.challengeIndex+1)/challenges.length*100)+'%';$('#challengeProgressText').textContent='Scenario '+(state.challengeIndex+1)+' of '+challenges.length;$('#challengeCard').innerHTML='<div class="scenario-kicker">SCENARIO '+String(state.challengeIndex+1).padStart(2,'0')+' / 05</div><h2 class="scenario-title">'+c.title+'</h2><p class="scenario-description">'+c.desc+'</p><div class="scenario-evidence">'+c.evidence.map(x=>'<div class="evidence-row"><span>↳</span>'+x+'</div>').join('')+'</div><div class="scenario-question">'+c.q+'</div><div class="answer-options">'+c.opts.map((o,i)=>'<button class="answer-option '+(answered?(i===c.correct?'correct':i===answered.choice?'incorrect':''):'')+'" data-challenge-option="'+i+'" '+(answered?'disabled':'')+'><span class="option-letter">'+String.fromCharCode(65+i)+'</span>'+o+'</button>').join('')+'</div>'+(answered?'<div class="feedback-box '+(answered.correct?'':'bad')+'"><b>'+(answered.correct?'✓ Good reasoning':'↻ Reconsider the evidence')+'</b><p>'+c.explain+'</p><p><b>Hint:</b> Focus on the stated objective and the evidence, not just the appearance.</p></div>':'')+'<div class="challenge-actions"><button class="btn btn-quiet" id="challengeRestart">↺ Restart</button><button class="btn btn-primary" id="challengeNext" '+(!answered?'disabled':'')+'>'+(state.challengeIndex===4?'Review results':'Next scenario')+' <span>→</span></button></div>';$$('[data-challenge-option]').forEach(b=>b.addEventListener('click',()=>{const choice=+b.dataset.challengeOption,correct=choice===c.correct;state.challengeAnswers[state.challengeIndex]={choice,correct};if(correct)state.challengeScore++;else state.errorsCorrected++;state.history.push('Challenge '+(state.challengeIndex+1)+': '+(correct?'correct diagnosis':'reviewed an incorrect diagnosis'));state.skills.add('error-detection');renderChallenge();updateProgress();save()}));$('#challengeNext').addEventListener('click',()=>{if(state.challengeIndex<4){state.challengeIndex++;renderChallenge()}else{toast('Challenge complete. Score: '+state.challengeScore+'/5');state.challengeIndex=0;renderChallenge()}save()});$('#challengeRestart').addEventListener('click',()=>{state.challengeIndex=0;state.challengeAnswers={};state.challengeScore=0;renderChallenge();save()})}
function renderQuiz(){const q=questions[state.quizIndex];const answer=state.quizAnswers[state.quizIndex];const answered=Object.keys(state.quizAnswers).length;$('#quizScore').textContent=state.quizScore+'/'+questions.length;$('#quizAnswered').textContent=answered+' / '+questions.length;$('#quizCorrect').textContent=state.quizScore;$('#quizProgress').style.width=(answered/questions.length*100)+'%';$('#quizMastered').textContent=state.quizScore;$('#quizCard').innerHTML=state.quizComplete?'<div class="quiz-question-count">ASSESSMENT COMPLETE</div><h2 class="quiz-question-title">Nice work. You finished the knowledge check.</h2><p class="scenario-description">Your score is '+state.quizScore+' out of '+questions.length+'. Review the explanations, then retake the quiz to practise again.</p><div class="feedback-box"><b>Learning note</b><p>Scientific interpretation depends on formulation-specific evidence. Simulated readings and illustrative appearances do not validate real preparations or identify organisms.</p></div><button class="btn btn-primary" id="quizRetake">Retake quiz <span>↻</span></button>': '<div class="quiz-question-count">QUESTION '+(state.quizIndex+1)+' / '+questions.length+' · MEDIA FUNDAMENTALS</div><h2 class="quiz-question-title">'+q.q+'</h2><div class="answer-options">'+q.opts.map((o,i)=>'<button class="answer-option '+(answer?(i===q.a?'correct':i===answer.choice?'incorrect':''):'')+'" data-quiz-option="'+i+'" '+(answer?'disabled':'')+'><span class="option-letter">'+String.fromCharCode(65+i)+'</span>'+o+'</button>').join('')+'</div>'+(answer?'<div class="feedback-box '+(answer.correct?'':'bad')+'"><b>'+(answer.correct?'✓ Correct':'↻ Keep learning')+'</b><p>'+q.explain+'</p></div>':'')+'<div class="challenge-actions"><button class="btn btn-quiet" id="quizReset">↺ Restart</button><button class="btn btn-primary" id="quizNext" '+(!answer?'disabled':'')+'>'+(state.quizIndex===questions.length-1?'See results':'Next question')+' <span>→</span></button></div>';$$('[data-quiz-option]').forEach(b=>b.addEventListener('click',()=>{const choice=+b.dataset.quizOption,correct=choice===q.a;state.quizAnswers[state.quizIndex]={choice,correct};if(correct)state.quizScore++;state.skills.add('quiz');state.history.push('Quiz question '+(state.quizIndex+1)+': '+(correct?'correct':'reviewed'));renderQuiz();updateProgress();save()}));const next=$('#quizNext');if(next)next.addEventListener('click',()=>{if(state.quizIndex<questions.length-1)state.quizIndex++;else state.quizComplete=true;renderQuiz();save()});const reset=$('#quizReset');if(reset)reset.addEventListener('click',restartQuiz);const retake=$('#quizRetake');if(retake)retake.addEventListener('click',restartQuiz)}
function restartQuiz(){state.quizIndex=0;state.quizAnswers={};state.quizScore=0;state.quizComplete=false;state.quizStarted=Date.now();renderQuiz();save()}
function updateProgress(){const completed=new Set(state.completedStages).size;const totalSkills=state.skills.size;const quizDone=state.quizComplete?1:0;const progress=Math.round(Math.min(100,(completed/6*.55)+(totalSkills/6*.25)+(Object.keys(state.challengeAnswers).length/5*.1)+(Object.keys(state.quizAnswers).length/8*.1))*100);$('#progressValue').textContent=progress+'%';$('#progressBar').style.width=progress+'%';$('#skillCount').textContent=Math.min(6,totalSkills);save()}
function renderReport(){const m=current();const amount=scaledAmounts();const quizAnswered=Object.keys(state.quizAnswers).length;const challAnswered=Object.keys(state.challengeAnswers).length;const elapsed=Math.max(1,Math.round((Date.now()-state.quizStarted)/60000));$('#reportContent').innerHTML='<div class="report-hero"><div><div class="panel-kicker">VIRTUAL EXPERIMENT SUMMARY</div><h2>'+m.name+'</h2><p>CultureCraft simulated preparation record · Generated '+new Date().toLocaleString()+'<br>Educational simulation only — not a real laboratory record.</p></div><span class="report-stamp">'+(state.plated?'PLATE SIMULATED':'IN PROGRESS')+'</span></div><div class="report-metrics"><div class="report-metric"><span>Target volume</span><b>'+state.volume+' mL</b></div><div class="report-metric"><span>Stages completed</span><b>'+state.completedStages.length+' / 6</b></div><div class="report-metric"><span>Challenge score</span><b>'+state.challengeScore+' / 5</b></div><div class="report-metric"><span>Quiz score</span><b>'+state.quizScore+' / 8</b></div></div><div class="report-section"><h3>Medium and ingredient calculations</h3><div class="report-list"><div class="report-row"><span>Selected medium</span><b>'+m.name+'</b></div><div class="report-row"><span>Purpose</span><b>'+m.classif+'</b></div><div class="report-row"><span>Representative appearance</span><b>'+m.appearance+'</b></div>'+Object.entries(amount).map(([k,v])=>'<div class="report-row"><span>'+ingredientLabels()[k]+' · illustrative scaled amount</span><b>'+v.toFixed(2)+' g</b></div>').join('')+'<div class="report-row"><span>Simulated balance reading</span><b>'+state.balance.toFixed(2)+' g</b></div><div class="report-row"><span>Simplified pH model reading</span><b>'+state.ph.toFixed(1)+' · simulated</b></div></div></div><div class="report-section"><h3>Virtual stages</h3><div class="report-list">'+stageData.map((s,i)=>'<div class="report-row"><span>'+String(i+1).padStart(2,'0')+' · '+s.title+'</span><b>'+(state.completedStages.includes(i)?'Completed':'Not completed')+'</b></div>').join('')+'<div class="report-row"><span>Virtual processing</span><b>'+(state.processed?'Simulated':'Not completed')+'</b></div><div class="report-row"><span>Cooling</span><b>'+(state.cooled?'Simulated':'Not completed')+'</b></div><div class="report-row"><span>Final plate</span><b>'+(state.plated?'Prepared · uninoculated':'Not prepared')+'</b></div><div class="report-row"><span>Challenge scenarios answered</span><b>'+challAnswered+' / 5</b></div><div class="report-row"><span>Quiz questions answered</span><b>'+quizAnswered+' / 8</b></div><div class="report-row"><span>Recorded learning actions</span><b>'+state.history.length+'</b></div></div></div><div class="report-section"><h3>Scientific reflection</h3><div class="report-outcome">'+m.summary+' '+m.notes+' This report records simulated states only. It does not establish real composition, correct pH, successful sterilization, contamination status or organism identity.</div></div><div class="report-section"><h3>Learning outcomes</h3><div class="report-list">'+['Distinguish medium purpose from formulation-specific use.','Explain the role of ingredient categories.','Apply proportional scaling arithmetic to illustrative values.','Interpret simulated pH and equipment states with appropriate caution.','Recognize why appearance alone does not prove sterility or identify organisms.'].map((x,i)=>'<div class="report-row"><span>'+(i+1)+'. '+x+'</span><b>Learning objective</b></div>').join('')+'</div></div><div class="detail-note" style="margin-top:20px">Safety reminder: Real laboratory work must follow instructor-approved procedures, product labels, validated methods and institutional biosafety requirements. Do not handle unknown or potentially pathogenic organisms based on this simulation.</div>';state.lastReport={medium:m.name,volume:state.volume,generated:new Date().toISOString()}}
function downloadReport(){renderReport();const textReport='CULTURECRAFT — VIRTUAL EXPERIMENT REPORT\nGenerated: '+new Date().toLocaleString()+'\n\nMedium: '+current().name+'\nTarget volume: '+state.volume+' mL\nPurpose: '+current().purpose+'\nAppearance: '+current().appearance+'\n\nILLUSTRATIVE CALCULATIONS\n'+Object.entries(scaledAmounts()).map(([k,v])=>ingredientLabels()[k]+': '+v.toFixed(2)+' g').join('\n')+'\n\nSIMULATED STATES\nBalance: '+state.balance.toFixed(2)+' g\nSimplified pH: '+state.ph.toFixed(1)+'\nStages completed: '+state.completedStages.length+'/6\nProcessing: '+(state.processed?'simulated':'not completed')+'\nCooling: '+(state.cooled?'simulated':'not completed')+'\nPlate: '+(state.plated?'prepared, uninoculated':'not prepared')+'\nChallenge score: '+state.challengeScore+'/5\nQuiz score: '+state.quizScore+'/8\n\nLEARNING NOTE\n'+current().summary+'\n\nSAFETY AND LIMITATIONS\nThis file describes a virtual educational simulation only. Values are illustrative and are not a validated recipe. It cannot establish real composition, pH, sterility or organism identity. Real laboratory work must follow approved product labels, SOPs and biosafety rules.\n';const blob=new Blob([textReport],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='culturecraft-virtual-experiment-report.txt';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Report downloaded.');}
function showModal(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modalBackdrop').hidden=false;$('#modalClose').focus()}
function closeModal(){$('#modalBackdrop').hidden=true}
function bindGlobal(){$$('.nav-item').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));$$('[data-goto]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.goto)));$('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#helpBtn').addEventListener('click',()=>showModal('About CultureCraft','<p>CultureCraft is an interactive educational simulation for biotechnology and microbiology students. It models concepts behind culture media selection, ingredient functions, proportional calculations, pH, processing stages and scientific interpretation.</p><ul><li>All measurements, pH values and equipment states are simulated.</li><li>Ingredient quantities are illustrative scaling examples, not universal formulations or real-world preparation instructions.</li><li>Animations cannot verify sterility, and illustrative colony appearances do not identify organisms.</li><li>Follow instructor-approved procedures, product labels, validated methods and institutional biosafety requirements for any real lab work.</li></ul>'));$('#modalClose').addEventListener('click',closeModal);$('#modalOk').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('#volumeInput').addEventListener('change',e=>{const v=Math.max(50,Math.min(1000,Math.round((+e.target.value||250)/50)*50));state.volume=v;e.target.value=v;renderLab();updateProgress();save();toast('Illustrative quantities scaled to '+v+' mL.')});$('#resetLab').addEventListener('click',resetLab);$('#whyBtn').addEventListener('click',()=>{$('#whyContent').hidden=!$('#whyContent').hidden;$('#whyBtn span').textContent=$('#whyContent').hidden?'＋':'−'});$('#prevStep').addEventListener('click',()=>setStage(state.stage-1));$('#nextStep').addEventListener('click',()=>{if(state.stage===5){state.completedStages=[...new Set([...state.completedStages,5])];updateProgress();save();go('report');toast('Experiment report updated.');return}setStage(state.stage+1)});$('#librarySearch').addEventListener('input',renderLibrary);$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.libraryFilter=b.dataset.filter;renderLibrary()}));$('#compareBtn').addEventListener('click',()=>renderCompare());$$('[data-pair]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.pair==='all'){renderCompare('all');return}const p=b.dataset.pair.split(',');$('#compareA').value=p[0];$('#compareB').value=p[1];renderCompare()}));$('#downloadReport').addEventListener('click',downloadReport);$('#compareA').addEventListener('change',()=>renderCompare());$('#compareB').addEventListener('change',()=>renderCompare());$('#restartQuiz').addEventListener('click',restartQuiz);$$('.bench-object').forEach(b=>b.addEventListener('click',()=>renderTool(b.dataset.tool)));$('#workflowList').addEventListener('click',e=>{const b=e.target.closest('[data-stage]');if(b)setStage(+b.dataset.stage)})}
load();bindGlobal();fillCompareSelects();renderLab();renderLibrary();renderEquipment();renderCompare();renderChallenge();renderQuiz();renderReport();updateProgress();
})();